# =========================================================
# 11_Figure6_persistent_clonotype_remodeling.R
# Purpose:
#   Visual cleanup of Figure 6 v2 without changing analysis.
#
# Input:
#   Uses tables generated by:
#   62A_4_replot_Figure6_v2_patient_level_main.R
#
# Main goals:
#   - Use correct folders from 62A_4
#   - Improve readability
#   - Keep patient-level panels as primary support
#   - Keep clone-level panel explicitly exploratory
#   - Preserve significance/trend labels:
#       * q < 0.05
#       trend q < 0.15
#
# Analytical changes:
#   None.
# =========================================================

suppressPackageStartupMessages({
  library(tidyverse)
  library(fs)
  library(patchwork)
})

# =========================================================
# =========================================================
# 1. Paths
# =========================================================

# Repository root is inferred from this script location.

script_file <- tryCatch(
  normalizePath(
    sys.frame(1)$ofile,
    winslash = "/",
    mustWork = TRUE
  ),
  error = function(e) NA_character_
)

if (is.na(script_file)) {
  stop("Run this script with source().")
}

script_dir <- dirname(script_file)

project_root <- normalizePath(
  file.path(script_dir, ".."),
  winslash = "/",
  mustWork = TRUE
)

dir_input_tables <- file.path(
  project_root,
  "data",
  "tcr",
  "figure6"
)

dir_output_plots <- file.path(
  project_root,
  "results",
  "figures",
  "Figure6"
)

dir_output_tables <- file.path(
  project_root,
  "results",
  "tables",
  "Figure6_persistent_clonotype_remodeling"
)

dir_create(
  dir_output_plots
)

dir_create(
  dir_output_tables
)

cat("\n[Input table folder]\n")
cat(dir_input_tables, "\n")

cat("\n[Files available in input folder]\n")
print(
  list.files(
    dir_input_tables,
    full.names = FALSE
  )
)

# 2. Required input files from 62A_4
# =========================================================

path_A_vals  <- file.path(dir_input_tables, "Fig6v2A_clonotype_fate_distribution_values.csv")
path_B_vals  <- file.path(dir_input_tables, "Fig6v2B_patient_level_RF240_global_delta_values.csv")
path_B_stats <- file.path(dir_input_tables, "Fig6v2B_patient_level_RF240_global_delta_stats.csv")
path_C_vals  <- file.path(dir_input_tables, "Fig6v2C_patient_level_RF240_delta_by_fate_values.csv")
path_C_stats <- file.path(dir_input_tables, "Fig6v2C_patient_level_RF240_delta_by_fate_stats.csv")
path_D_vals  <- file.path(dir_input_tables, "Fig6v2D_clone_level_RF240_global_delta_values.csv")
path_D_stats <- file.path(dir_input_tables, "Fig6v2D_clone_level_RF240_global_delta_stats.csv")
path_E_vals  <- file.path(dir_input_tables, "Fig6v2E_RF240_global_state_transition_values.csv")
path_F_vals  <- file.path(dir_input_tables, "Fig6v2F_patient_level_module_delta_by_fate_values.csv")

required_files <- c(
  path_A_vals,
  path_B_vals,
  path_B_stats,
  path_C_vals,
  path_C_stats,
  path_D_vals,
  path_D_stats,
  path_E_vals,
  path_F_vals
)

missing_files <- required_files[!file.exists(required_files)]

if (length(missing_files) > 0) {
  stop(
    "Missing required input files:\n",
    paste(missing_files, collapse = "\n")
  )
}

# =========================================================
# 3. Helper functions
# =========================================================

format_q_for_plot <- function(q) {
  case_when(
    is.na(q) ~ "",
    q < 0.001 ~ "***",
    q < 0.01 ~ "**",
    q < 0.05 ~ "*",
    q < 0.15 ~ paste0("trend\nq=", sprintf("%.3f", q)),
    TRUE ~ ""
  )
}

format_q_class <- function(q) {
  case_when(
    is.na(q) ~ "not_testable",
    q < 0.05 ~ "q_lt_0.05",
    q < 0.15 ~ "trend_q_lt_0.15",
    TRUE ~ "ns"
  )
}

save_plot_multi <- function(plot, filename_base, width, height) {
  
  ggsave(
    filename = file.path(dir_output_plots, paste0(filename_base, ".pdf")),
    plot = plot,
    width = width,
    height = height,
    units = "in"
  )
  
  ggsave(
    filename = file.path(dir_output_plots, paste0(filename_base, ".png")),
    plot = plot,
    width = width,
    height = height,
    units = "in",
    dpi = 300
  )
  
  ggsave(
    filename = file.path(dir_output_plots, paste0(filename_base, ".tiff")),
    plot = plot,
    width = width,
    height = height,
    units = "in",
    dpi = 300,
    compression = "lzw"
  )
}

theme_fig6 <- function(base_size = 8.5) {
  theme_bw(base_size = base_size) +
    theme(
      plot.title = element_text(face = "bold", size = base_size + 1),
      axis.title = element_text(size = base_size),
      axis.text = element_text(size = base_size - 1),
      strip.text = element_text(face = "bold", size = base_size - 1),
      legend.position = "top",
      panel.grid.minor = element_blank()
    )
}

# =========================================================
# 4. Labels and palettes
# =========================================================

