# =========================================================
# 6. Panel A: clonotype fate distribution
# =========================================================

A_plot <- A_vals %>%
  mutate(
    response_pcr = factor(response_pcr, levels = response_order),
    comparison_label = factor(comparison_label, levels = c("Base → PD1", "Base → RTPD1")),
    fate_label = factor(fate_label, levels = fate_order_A)
  ) %>%
  filter(!is.na(fate_label))

write_csv(
  A_plot,
  file.path(dir_output_tables, "Fig6v3A_clonotype_fate_distribution_values.csv")
)

pA <- ggplot(
  A_plot,
  aes(
    x = fate_label,
    y = prop_clonotypes,
    fill = response_pcr
