  facet_wrap(~ comparison_label, scales = "free_x", nrow = 1) +
  scale_fill_manual(values = pal_response, drop = FALSE) +
  labs(
    title = "A. Clonotype fate distribution",
    x = NULL,
    y = "Proportion of clonotypes",
    fill = "Response"
  ) +
  theme_fig6(8.2) +
  theme(
    axis.text.x = element_text(angle = 40, hjust = 1, size = 6.3)
  )

# =========================================================
# 7. Panel B: patient-level RF240 global change
# =========================================================

